head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > E > ondblclick]<br/>Calendar 컴포넌트를 마우스로 더블클릭할 때 발생합니다.",
    "validation" : [
        "Calendar 컴포넌트를 마우스로 더블클릭할 때 ondblclick 이벤트가 발생합니다.",
        "더블클릭 시 onclick 이벤트가 2번 먼저 발생한 후 ondblclick 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨: 수동 테스트 안내 (validation 1, 2)
    $c.gcm.createLabel('label="[수동 테스트 안내] Calendar 컴포넌트의 임의 영역(날짜 셀, 헤더, 푸터 등)을 마우스로 더블클릭하면 onclick 이벤트가 2번 발생한 후 ondblclick 이벤트가 발생합니다."', '', 'label1');

    let properties = {}

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick", "ondblclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// 더블클릭 시 onclick 이벤트가 2번 먼저 발생 (validation 2: 이벤트 순서 검증)
scwin.target1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onclick=====");    
};



// Calendar 컴포넌트를 마우스로 더블클릭할 때 발생 (validation 1, 2)
scwin.target1_ondblclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ondblclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
};
